SELECT a.*, m.display_name AS applicant_name, v.name AS agent_name, v.config_json AS agent_config_json FROM agent_hire_request a JOIN enterprise_member m ON m.enterprise_id = a.enterprise_id AND m.user_id = a.user_id JOIN resource r ON r.enterprise_id = a.enterprise_id AND r.id = a.agent_id JOIN resource_version v ON v.enterprise_id = r.enterprise_id AND v.id = r.published_version_id WHERE a.enterprise_id = #{enterprise} AND ((#{includeOwn} AND a.user_id = #{user}) OR (
)
)
AND (a.created_at < #{cursor.time} OR (a.created_at = #{cursor.time} AND a.id < #{cursor.id}))
ORDER BY a.created_at DESC, a.id DESC LIMIT #{limit}

